import { JobsLogContext } from '@mesx/common-lib';

/**
 * Creates a log context object for job logging.
 * @param serviceName The name of the service generating the log.
 * @param method The method or operation being logged.
 * @param plant (Optional) The plant identifier.
 * @param object (Optional) The object related to the log entry.
 * @param userId (Optional) The user ID associated with the log entry.
 * @returns A JobsLogContext object containing the provided context information.
 */
export function createLogContext(
  serviceName: string,
  method: string,
  plant?: number,
  object?: string,
  userId?: string,
): JobsLogContext {
  return {
    method,
    object,
    plant,
    service: serviceName,
    userId,
  };
}

