export interface Mapping {
  /**
   * Source table in SAP DMC
   */
  source: string;

  /**
   * Target table in MESX
   */
  destination: string;

  /**
   * Key fields source and associated column in target structure
   */
  keys: Array<KeyMapping>;

  /**
   * Column mapping
   */
  columnMappings: Array<ColumnMapping>;
}

export interface KeyMapping {
  /**
   * Source field
   */
  keySource: string;

  /**
   * Target field
   */
  keyDestination: string;
  /**
   * Type field
   */
  type?: string;
  /**
   * AllowEmpty field
   */
  allowEmpty?: boolean;
}

export interface ColumnMapping {
  /**
   * Source field
   */
  columnSource: string;

  /**
   * Target field
   */
  columnDestination: string;
  /**
   * Type field
   */
  type?: string;
  /**
   * AllowEmpty field
   */
  allowEmpty?: boolean;
}

export type MappedOutput =
  | ShiftTrackingStatus
  | ShiftTrackingDtl
  | AssemblyLineConfig
  | ActionsOnProduction
  | CadenceConfig
  | RoutingPrt;

import { Module } from '@nestjs/common';
import { MappingService } from '@/common/mapping/service/mapping.service';
import { MappingUtilsService } from '@/common/mapping/utils/mapping.utils';

@Module({
  exports: [MappingService],
  providers: [MappingService, MappingUtilsService],
})
export class MappingModule {}

import * as crypto from 'node:crypto';
import { JobsLogContext } from '@mesx/common-lib';
import { Injectable } from '@nestjs/common';

import { AppLogger } from '@/common/logger/app-logger';
import {
  MappedOutput,
  Mapping,
} from '@/common/mapping/interface/mapping.model';
import { MappingUtilsService } from '@/common/mapping/utils/mapping.utils';

import { PlantsResponseDto } from '@/common/subscribe/dtos/plant.response.dto';
import { CombinedDtoWithIndex } from '@/dapr/dtos/combined.dto';
import { IngestionEventTrackingDTO } from '@/modules/ingestion-event-tracking/ingestion-event-tracking.dto.';

@Injectable()
export class MappingService {
  private static isEmptyValue(value: unknown): boolean {
    return value === undefined || value === '' || value === null;
  }

  private readonly mappings: Array<Mapping>;

  public constructor(
    private readonly mappingUtils: MappingUtilsService,
    private readonly customLogger: AppLogger,
  ) {
    this.mappings = this.loadMappings();
  }

  /**
   * Load mapping definition
   * @returns mapping
   */
  private loadMappings(): Array<Mapping> {
    const context: JobsLogContext = {
      method: 'loadMappings',
      service: 'MappingService',
    };
    try {
      return this.mappingUtils.loadMappings(
        '../config/identifier-mapping.json',
      );
    } catch (error) {
      this.customLogger.error(
        `Failed to load mappings: ${error.message}`,
        context,
      );
      throw error;
    }
  }

  /**
   * Retrieve the mapping rules between
   * source table and target table
   * @param source source table
   * @param destination  destination table
   * @returns mapping
   */
  private getMapping(source: string, destination: string): Mapping {
    const mapping = this.mappings.find(
      (f) => f.source === source && f.destination === destination,
    );

    if (!mapping) {
      throw new Error(
        `No mapping found for source '${source}' and destination '${destination}'.`,
      );
    }
    return mapping;
  }

  /**
   * Build target record by applying mapping data
   * @param source source table name
   * @param data raw record
   * @param listPlant List Plant
   * @returns mapped data
   */
  public mapData(
    source: string,
    data: CombinedDtoWithIndex,
    listPlant: Array<PlantsResponseDto>,
  ): {
    destination: string;
    ingestionEventTracking: IngestionEventTrackingDTO | undefined;
    mappedData: MappedOutput;
  } {
    const destination = this.getDestinationTable(source);
    const mapping = this.getMapping(source, destination);

    const { keyResults, mappedData: initialMap } = this.processKeyFields(
      mapping,
      data,
      listPlant,
    );
    const { keysValue, sourceDatabase } = keyResults;

    const isWip = this.mappingUtils.isWIP(sourceDatabase);
    const plantId = initialMap['plant'] as number | undefined;
    const timeZone = plantId
      ? this.mappingUtils.getTimeZoneForPlant(plantId, listPlant)
      : undefined;

    const columnMap = this.processColumnMappings(
      mapping,
      data,
      listPlant,
      isWip,
      timeZone,
      sourceDatabase,
    );

    const finalMapped: Record<string, unknown> = {
      ...initialMap,
      ...columnMap,
    };

    const { __source_change_lsn: changeLsn, __source_ts_ms: tsMs } = data;
    const ingestionEventTracking = this.buildIngestionEventTracking(
      source,
      destination,
      keysValue,
      changeLsn,
      tsMs,
    );

    // Cast through unknown to satisfy strict compiler when dynamic mapping is used
    return {
      destination,
      ingestionEventTracking,
      mappedData: finalMapped as unknown as MappedOutput,
    };
  }

  /**
   * Returns all destination names configured for a given source (fan-out aware).
   * @param source Source table name
   * @returns Array of destination table names
   */
  public getDestinationsForSource(source: string): Array<string> {
    return this.mappings
      .filter((m) => m.source === source)
      .map((m) => m.destination);
  }

  /**
   * Map a source record into all configured destinations (fan-out multi-entity support).
   * @param source Source table name
   * @param data Raw record
   * @param listPlant Plant list for time zone resolution
   * @returns Array of mapped outputs per destination
   */
  public mapAllData(
    source: string,
    data: CombinedDtoWithIndex,
    listPlant: Array<PlantsResponseDto>,
  ): Array<{
    destination: string;
    ingestionEventTracking: IngestionEventTrackingDTO | undefined;
    mappedData: MappedOutput;
  }> {
    const destinations = this.getDestinationsForSource(source);
    const outputs: Array<{
      destination: string;
      ingestionEventTracking: IngestionEventTrackingDTO | undefined;
      mappedData: MappedOutput;
    }> = [];
    for (const destination of destinations) {
      const mapping = this.getMapping(source, destination);
      const { keyResults, mappedData: initialMap } = this.processKeyFields(
        mapping,
        data,
        listPlant,
      );
      const { keysValue, sourceDatabase } = keyResults;
      const isWip = this.mappingUtils.isWIP(sourceDatabase);
      const plantId = initialMap['plant'] as number | undefined;
      const timeZone = plantId
        ? this.mappingUtils.getTimeZoneForPlant(plantId, listPlant)
        : undefined;
      const columnMap = this.processColumnMappings(
        mapping,
        data,
        listPlant,
        isWip,
        timeZone,
        sourceDatabase,
      );
      const finalMapped: Record<string, unknown> = {
        ...initialMap,
        ...columnMap,
      };
      const { __source_change_lsn: changeLsn, __source_ts_ms: tsMs } = data;
      const ingestionEventTracking = this.buildIngestionEventTracking(
        source,
        destination,
        keysValue,
        changeLsn,
        tsMs,
      );
      outputs.push({
        destination,
        ingestionEventTracking,
        mappedData: finalMapped as unknown as MappedOutput,
      });
    }
    return outputs;
  }

  /**
   * Check primary keys
   * @param source source table name
   * @param data raw record
   * @returns boolean
   */
  public checkPrimaryKeys(source: string, data: CombinedDtoWithIndex): boolean {
    const destination = this.getDestinationTable(source);
    const mapping = this.getMapping(source, destination);
    return mapping.keys.every((key) => {
      const keySourceValue = data[key.keySource] ?? null;
      return (
        keySourceValue !== null &&
        keySourceValue !== undefined &&
        keySourceValue !== ''
      );
    });
  }

  /**
   * Identify the target table
   * @param sourceTable source table
   * @returns destination table string
   */
  public getDestinationTable(sourceTable: string): string {
    const context: JobsLogContext = {
      method: 'getDestinationTable',
      service: 'MappingService',
    };
    const mapping = this.mappings.find((m) => m.source === sourceTable);
    if (!mapping) {
      const errorMessage = `Mapping not found for source table ${sourceTable}`;
      this.customLogger.error(errorMessage, context);
      throw new Error(errorMessage);
    }

    return mapping.destination;
  }

  private generateHash(
    sourceTable: string,
    keys: string,
    destinationTable = '',
  ): string {
    try {
      const destinationTableValue = destinationTable ?? '';
      return crypto
        .createHash('sha256')
        .update(`${sourceTable}:${keys}:${destinationTableValue}`)
        .digest('hex');
    } catch (error) {
      this.customLogger.error(
        `error when generation the hash key ${error}`,
        error.stack,
      );
      return '';
    }
  }

  /**
   * Process and map primary key fields.
   * @param mapping Mapping definition
   * @param data Source record
   * @param listPlant Plant list (for timezone resolution if plant appears among keys)
   * @returns key results and initial mapped structure
   */
  private processKeyFields(
    mapping: Mapping,
    data: CombinedDtoWithIndex,
    listPlant: Array<PlantsResponseDto>,
  ): {
    keyResults: { keysValue: string; sourceDatabase: string | undefined };
    mappedData: Record<string, unknown>;
  } {
    const mappedData: Record<string, unknown> = {};
    let keysValue = '';
    const { __source_db: sourceDatabase } = data;
    for (const key of mapping.keys) {
      const keySourceValue = data[key.keySource];
      if (
        !MappingService.isEmptyValue(keySourceValue) ||
        (keySourceValue === '' && key.allowEmpty)
      ) {
        keysValue += keySourceValue as string;
        mappedData[key.keyDestination] = this.mapPossiblyTimestamp(
          keySourceValue,
          key.type,
          mappedData['plant'] as number | undefined,
          sourceDatabase,
          listPlant,
        );
      }
    }
    return { keyResults: { keysValue, sourceDatabase }, mappedData };
  }

  /**
   * Process non-key column mappings.
   * @param mapping Mapping definition
   * @param data Source record
   * @param listPlant Plant list
   * @param isWip Whether source DB is WIP
   * @param timeZone Resolved plant timezone
   * @param sourceDatabase Source database name
   * @returns Record of mapped column values
   */
  private processColumnMappings(
    mapping: Mapping,
    data: CombinedDtoWithIndex,
    listPlant: Array<PlantsResponseDto>,
    isWip: boolean,
    timeZone: string | undefined,
    sourceDatabase: string | undefined,
  ): Record<string, unknown> {
    const result: Record<string, unknown> = {};
    for (const columnMapping of mapping.columnMappings) {
      const rawValue = data[columnMapping.columnSource];
      if (MappingService.isEmptyValue(rawValue)) {
        // Skip empty
        if (rawValue === '') {
          result[columnMapping.columnDestination] = columnMapping.allowEmpty
            ? ''
            : null;
        }
      } else if (
        !isWip &&
        columnMapping.columnSource.toUpperCase() === 'HOUR'
      ) {
        // Hour handling (local -> UTC)
        result[columnMapping.columnDestination] = this.convertHourToUtcString(
          rawValue?.toString() ?? '',
          timeZone,
        );
      } else {
        // Timestamp / normal value
        result[columnMapping.columnDestination] = this.mapPossiblyTimestamp(
          rawValue,
          columnMapping.type,
          (result['plant'] as number | undefined) ??
            (data['plant'] as number | undefined) ??
            undefined,
          sourceDatabase,
          listPlant,
          isWip,
          timeZone,
        );
      }
    }
    return result;
  }

  /**
   * Build ingestion event tracking structure.
   */
  /**
   * Build ingestion event tracking structure.
   * @param source Source table name
   * @param destination Destination table name
   * @param keysValue Concatenated key values
   * @param sourceChangeLsn Source change LSN (hex)
   * @param sourcetsMs Source timestamp ms
   * @returns IngestionEventTrackingDTO or undefined when no LSN
   */
  private buildIngestionEventTracking(
    source: string,
    destination: string,
    keysValue: string,
    sourceChangeLsn?: string,
    sourcetsMs?: number,
  ): IngestionEventTrackingDTO | undefined {
    const changeLastLsn = sourceChangeLsn
      ? this.mappingUtils.hexStringToNumber(sourceChangeLsn)
      : '';
    if (!changeLastLsn) return undefined;
    return {
      changeLastLsn,
      destinationTable: destination,
      hashKey: this.generateHash(source, keysValue, destination),
      keys: keysValue,
      lastTimestamp: sourcetsMs ?? 0,
      sourceTable: source,
    };
  }

  /**
   * Maps a value, converting to Date if it's a timestamp field.
   */
  /**
   * Maps a raw field value, converting to Date when the field type indicates a timestamp.
   * @param rawValue Raw value from source row
   * @param fieldType Field type descriptor
   * @param plant Plant id (optional)
   * @param sourceDatabase Source database name
   * @param listPlant Plant list for timezone resolution
   * @param isWip Whether source DB is WIP
   * @param timeZone Resolved timezone
   * @returns Converted Date or original rawValue
   */
  private mapPossiblyTimestamp(
    rawValue: unknown,
    fieldType: string | undefined,
    plant: number | undefined,
    sourceDatabase: string | undefined,
    listPlant: Array<PlantsResponseDto>,
    isWip?: boolean,
    timeZone?: string,
  ): unknown {
    const isTimestamp = this.mappingUtils.findFieldWithTimestamp(fieldType);
    if (!isTimestamp) return rawValue;
    const effectiveIsWip = isWip ?? this.mappingUtils.isWIP(sourceDatabase);
    const effectiveTimeZone =
      timeZone ??
      (plant
        ? this.mappingUtils.getTimeZoneForPlant(plant, listPlant) ?? undefined
        : undefined);
    const date = this.mappingUtils.convertTimestampToDate(
      Number(rawValue),
      effectiveIsWip,
      effectiveTimeZone,
    );
    return date ?? rawValue;
  }

  /**
   * Converts local hour raw value to UTC string using mapping utils.
   */
  /**
   * Convert a local hour to its UTC hour string using timezone conversion.
   * @param rawValue Local hour raw value
   * @param timeZone Plant timezone string
   * @returns UTC hour as string, or original value if conversion fails
   */
  private convertHourToUtcString(
    rawValue: string,
    timeZone: string | undefined,
  ): string {
    const localHour = Number(rawValue);
    if (Number.isNaN(localHour)) return rawValue;
    const utcHour = this.mappingUtils.convertPlantLocalHourToUtc(
      localHour,
      timeZone,
    );
    const hourNumeric = utcHour ?? localHour;
    return hourNumeric.toString().padStart(2, '0');
  }
}

// MappingUtils.ts

import * as fs from 'node:fs';
import * as path from 'node:path/posix';
import { JobsLogContext } from '@mesx/common-lib';
import { Injectable } from '@nestjs/common';
import { DateTime } from 'luxon';
import { AppLogger } from '@/common/logger/app-logger';
import { Mapping } from '@/common/mapping/interface/mapping.model';
import { PlantsResponseDto } from '@/common/subscribe/dtos/plant.response.dto';

@Injectable()
export class MappingUtilsService {
  public constructor(private readonly customLogger: AppLogger) {}

  /**
   * Loads mappings from a file in the filesystem.
   * @param filePath - The relative path to the file containing mappings.
   * @returns An array of Mapping objects loaded from the file.
   * @throws {Error} Throws an error if the file cannot be read or parsed.
   */
  public loadMappings(filePath: string): Array<Mapping> {
    const context: JobsLogContext = {
      method: 'loadMappings',
      service: 'MappingUtilsService',
    };
    // Prefer process.cwd to satisfy lint rule against __dirname in certain build setups
    const absolutePath = path.resolve(__dirname, filePath);

    try {
      const rawData = fs.readFileSync(absolutePath, 'utf8');
      interface RawKey {
        keySource: string;
        keyDestination: string;
        type?: string;
      }
      interface RawColumn {
        columnSource: string;
        columnDestination: string;
        type?: string;
        allowEmpty?: boolean;
      }
      interface RawEntry {
        source?: string;
        destination?: string;
        keys?: Array<RawKey>;
        destinations?: Array<{ name: string; columns: Array<RawColumn> }>;
        columnMappings?: Array<RawColumn>;
      }
      const parsed = JSON.parse(rawData) as Array<RawEntry>;
      // Backward compatibility: flatten objects with destinations[] into Mapping objects
      const flattened: Array<Mapping> = [];
      for (const entry of parsed) {
        if (entry?.source && Array.isArray(entry?.destinations)) {
          for (const destination of entry.destinations ?? []) {
            flattened.push({
              source: entry.source,
              destination: destination?.name,
              keys: entry.keys ?? [],
              columnMappings: destination?.columns ?? [],
            });
          }
        } else if (entry?.source && entry?.destination) {
          flattened.push(entry as unknown as Mapping);
        }
      }
      return flattened;
    } catch (error) {
      this.customLogger.error(
        `Error loading mappings from file ${filePath}: ${error}`,
        context,
      );
      throw new Error(`Error loading mappings from file ${filePath}: ${error}`);
    }
  }

  /**
   * Determines if a given database is marked as "WIP" (Work In Progress).
   * @param databaseName - The name of the database.
   * @returns True if the database is "WIP", false otherwise.
   */
  public isWIP(databaseName: string | undefined): boolean {
    const context: JobsLogContext = {
      method: 'isWIP',
      service: 'MappingUtilsService',
    };
    if (databaseName) {
      return databaseName === 'WIP';
    }
    this.customLogger.error(`DB Name is missed : default isWip false`, context);
    return false;
  }

  /**
   * Checks if a field in the schema is of type timestamp.
   * @param type - The type of the field to check.
   * @returns True if the field is a timestamp, false if it is not, and undefined if the field is not found.
   */
  public findFieldWithTimestamp(type: string | undefined): boolean {
    const context: JobsLogContext = {
      method: 'findFieldWithTimestamp',
      service: 'MappingUtilsService',
    };
    try {
      if (type) {
        if (type === 'timestamp') {
          return true;
        }
        return false;
      }
      return false;
    } catch (error) {
      this.customLogger.error(
        `error in finding the type ${error.message}`,
        context,
      );
      return false;
    }
  }

  /**
   * Converts a timestamp to a Date object, considering the timezone offset if applicable.
   * @param timestamp - The timestamp to convert.
   * @param isWip - The source of the database is Wip or not.
   * @param timeZone - The timezone to consider for the conversion.
   * @returns The converted Date object, or undefined if the timestamp is invalid.
   */
  public convertTimestampToDate(
    timestamp: number,
    isWip: boolean,
    timeZone: string | undefined,
  ): Date | undefined {
    const context: JobsLogContext = {
      method: 'convertTimestampToDate',
      service: 'MappingUtilsService',
    };
    let utcDate: Date;
    if (timestamp === undefined) {
      this.customLogger.debug(`timestamp is undefined`, context);
      return undefined;
    }
    if (timestamp === 0) {
      this.customLogger.debug(`timestamp is null`, context);
      return undefined;
    }
    utcDate = new Date(timestamp);

    // Check no-end value is used represented by year 9999 and skip conversion
    if (utcDate.getFullYear() >= 9999)
      return new Date(9999, 11, 31, 23, 59, 59, 999);

    if (isWip) {
      utcDate = new Date(
        utcDate.getTime() + utcDate.getTimezoneOffset() * 60_000,
      );
      return utcDate;
    }
    if (timeZone) {
      // Const utcDateString = moment(timestamp).tz(timeZone).toISOString();
      const sourceDateTime = DateTime.fromMillis(timestamp, { zone: timeZone });
      const utcDateTime = sourceDateTime
        .toUTC()
        .minus({ milliseconds: sourceDateTime.offset * 60_000 });
      const utcDateString = utcDateTime.toISO();
      if (!utcDateString) {
        return undefined;
      }
      utcDate = new Date(utcDateString);
      utcDate = new Date(
        utcDate.getTime() + utcDate.getTimezoneOffset() * 60_000,
      );
    }
    return utcDate;
  }

  /**
   * Retrieves the timezone for a specific plant by its ID.
   * @param plantId - The ID of the plant.
   * @param plantList Array of list Plant
   * @returns The timezone associated with the plant, or undefined if it cannot be retrieved.
   */
  public getTimeZoneForPlant(
    plantId: number,
    plantList: Array<PlantsResponseDto>,
  ): string | undefined {
    const context: JobsLogContext = {
      method: 'getTimeZoneForPlant',
      service: 'MappingUtilsService',
    };
    try {
      const plantTimeZone = this.findPlantTimeZone(plantList, Number(plantId));

      return plantTimeZone;
    } catch (error) {
      this.customLogger.error(
        `Error retrieving time zone for plant ${plantId}: ${error.message}`,
        context,
        error.stack,
      );
      return undefined;
    }
  }

  /**
   * Finds the timezone for a specific plant by its ID from a list of plants.
   * @param plants - An array of plant response DTOs.
   * @param plantId - The ID of the plant to find.
   * @returns The timezone of the plant, or undefined if the plant is not found.
   */
  private findPlantTimeZone(
    plants: Array<PlantsResponseDto>,
    plantId: number,
  ): string | undefined {
    // Using this.customLogger to satisfy lint rule expecting this usage
    if (!plants || plants.length === 0) {
      this.customLogger.verbose('plants array empty when searching timezone', {
        method: 'findPlantTimeZone',
        service: 'MappingUtilsService',
      });
      return undefined;
    }
    return plants.find((plantFind) => plantFind.plantId === plantId)?.timeZone;
  }

  /**
   * Converts a hexadecimal string to a cleaned hexadecimal string (removing any non-hexadecimal characters).
   * @param hex - The hexadecimal string to clean.
   * @returns The cleaned hexadecimal string, or undefined if the input is invalid.
   */
  public hexStringToNumber(hex: string): string | undefined {
    const context: JobsLogContext = {
      method: 'hexStringToNumber',
      service: 'MappingUtilsService',
    };
    // Removing any colon (:) separators
    if (hex === undefined) {
      this.customLogger.error(`hex is undefined`, context);
      return undefined;
    }
    const cleanedHex = hex.replaceAll(/[^\da-f]/gi, '').toLowerCase();
    return cleanedHex;
  }

  /**
   * Converts a plant local hour to UTC based on its timezone.
   * @param localHour Hour in plant local time (0-23)
   * @param timezone Plant timezone (UTC-4, GMT+2, Europe/Paris, etc.)
   * @param referenceDate Optional reference date used for DST evaluation
   * @returns UTC hour (0-23) or undefined if invalid
   */
  public convertPlantLocalHourToUtc(
    localHour: number | undefined,
    timezone: string | undefined,
    referenceDate: Date = new Date(),
  ): number | undefined {
    const context: JobsLogContext = {
      method: 'convertPlantLocalHourToUtc',
      service: 'MappingUtilsService',
    };
    if (localHour === undefined || localHour === null) {
      this.customLogger.verbose('localHour is undefined/null', context);
      return undefined;
    }
    if (localHour < 0 || localHour > 23) {
      this.customLogger.error(`localHour out of range: ${localHour}`, context);
      return undefined;
    }
    if (!timezone) {
      return localHour; // Assume already UTC
    }
    try {
      const simpleTzRegex = /^(?:utc|gmt)([+-]\d{1,2})$/i;
      const simpleTzMatch = simpleTzRegex.exec(timezone);
      if (simpleTzMatch) {
        const offsetNumber = Number(simpleTzMatch[1]); // E.g. -4
        // Local = UTC + offset => UTC = Local - offset
        const utc = (localHour - offsetNumber + 24) % 24;
        return utc;
      }
      // IANA timezone path
      const dtLocal = DateTime.fromObject(
        {
          year: referenceDate.getUTCFullYear(),
          month: referenceDate.getUTCMonth() + 1,
          day: referenceDate.getUTCDate(),
          hour: localHour,
        },
        { zone: timezone },
      );
      if (!dtLocal.isValid) {
        this.customLogger.error(
          `Invalid local DateTime for timezone ${timezone}: ${dtLocal.invalidReason}`,
          context,
        );
        return undefined;
      }
      return dtLocal.toUTC().hour;
    } catch (error) {
      this.customLogger.error(
        `Error converting local hour to UTC with timezone ${timezone}: ${error.message}`,
        context,
        error.stack,
      );
      return undefined;
    }
  }
}

import { Module } from '@nestjs/common';
import { MutexManagerService } from '@/common/mutex-manager/mutex-manager.service';

@Module({
  exports: [MutexManagerService],
  providers: [MutexManagerService],
})
export class MutexManagerModule {}

import { Mutex } from 'async-mutex';

export class MutexManagerService {
  private readonly mutexes: Map<string, { mutex: Mutex; lastUsed: number }>;

  private readonly cleanupInterval: number; // In milliseconds

  private readonly cleanupThreshold: number; // Inactivity time threshold

  public constructor(cleanupInterval = 60_000, cleanupThreshold = 300_000) {
    // 60 seconds, 5 minutes threshold
    this.mutexes = new Map();
    this.cleanupInterval = cleanupInterval;
    this.cleanupThreshold = cleanupThreshold;
    this.startCleanupThread();
  }

  // Get or create a mutex for a given cacheKey
  public getMutex(cacheKey: string): Mutex {
    let mutexEntry = this.mutexes.get(cacheKey);
    if (mutexEntry) {
      mutexEntry.lastUsed = Date.now(); // Update the last used timestamp
    } else {
      mutexEntry = { lastUsed: Date.now(), mutex: new Mutex() };
      this.mutexes.set(cacheKey, mutexEntry);
    }
    return mutexEntry.mutex;
  }

  // Start a cleanup thread to remove inactive mutexes
  private startCleanupThread(): void {
    setInterval(() => {
      const now = Date.now();
      for (const [key, entry] of this.mutexes.entries()) {
        if (now - entry.lastUsed > this.cleanupThreshold) {
          this.mutexes.delete(key); // Remove inactive mutex
        }
      }
    }, this.cleanupInterval);
  }
}

