    topicName: string /* Add more topics as they're added */,
  ): EventHubSdkConfig & {
    checkpointInterval?: number;
    maxRetries?: number;
  } {
    if (topicName === 'shiftTracking') {
      return this.getShiftTrackingConfig();
    }

    if (topicName === 'shiftTrackingStatus') {
      return this.getShiftTrackingStatusConfig();
    }

    if (topicName === 'changeTools') {
      return this.getChangeToolsConfig();
    }

    if (topicName === 'routingPrt') {
      return this.getRoutingPrtConfig();
    }

    if (topicName === 'assemblyLineConfig') {
      return this.getAssemblyLineConfig();
    }
    if (topicName === 'cadenceConfig') {
      return this.getCadenceConfig();
    }
    if (topicName === 'actionsOnProd') {
      return this.getActionOnProdConfig();
    }
    throw new Error(`Configuration for topic ${topicName} not found`);
  }
