import { JobsLogContext } from '@mesx/common-lib';
import { Injectable, OnModuleInit } from '@nestjs/common';
import { EventEmitter2 } from '@nestjs/event-emitter';
import { DaprClient } from 'dapr-client';

import { checkPlantConsistency } from '../helpers/validations/check-plant-consistency';

import { AppLogger } from '@/common/logger/app-logger';
import { MappingService } from '@/common/mapping/service/mapping.service';

import { PlantsResponseDto } from '@/common/subscribe/dtos/plant.response.dto';
import { SubscribeMessageService } from '@/common/subscribe/subscribe.service';

import { RedisConfigService } from '@/config/redis/redis-store/redis-store.service';

import { CombinedDtoWithIndex } from '@/dapr/dtos/combined.dto';
import { RedisMessage } from '@/dapr/interface/redis-message-data.interface';
import { getListPlant } from '@/helpers/caches/get-plant-list';
import { emitSqlEvent } from '@/helpers/events/emit-sql-events';
import {
  decrementPendingMessageCount,
  incrementPendingMessageCount,
} from '@/helpers/statistics/pending-message-stats';

@Injectable()
export class DaprServiceApi implements OnModuleInit {
  public static createLogContext(
    method: string,
    plant?: number,
    object?: string,
    userId?: string,
  ): JobsLogContext {
    return { method, object, plant, service: DaprServiceApi.name, userId };
  }

  private plantList: Array<PlantsResponseDto> = [];

  private readonly daprClient: DaprClient;

  public constructor(
    private readonly eventEmitter: EventEmitter2,
    private readonly mappingService: MappingService,
    private readonly redisConfigService: RedisConfigService,
    private readonly subscribeMessageService: SubscribeMessageService,
    private readonly customLogger: AppLogger,
  ) {
    this.daprClient = new DaprClient();
  }

  public async initializePlant(): Promise<void> {
    this.plantList = await getListPlant(
      this.customLogger,
      this.daprClient,
      this.subscribeMessageService,
      this.redisConfigService.redisStoreAmr,
      this.redisConfigService.redisPlantKey,
    );
  }

  public async onModuleInit(): Promise<void> {
    await this.initializePlant();
  }

  /**
   * Process the message
   * @param message Mapped Data to process
   * @param sequenceNumber - The sequence number of the message
   */
  private async processMessage(
    message: RedisMessage,
    sequenceNumber: string | Array<string> | undefined,
  ): Promise<void> {
    const context: JobsLogContext = {
      method: 'processMessage',
      service: 'DaprService',
    };

    const { destination, operation, mappedData } = message;
    try {
      if (!operation) {
        return;
      }
      await emitSqlEvent(
        this.customLogger,
        context,
        this.eventEmitter,
        destination,
        mappedData,
        operation,
      );
    } catch (error) {
      this.customLogger.error(
        `Error processing Message with sequenceNumber ${sequenceNumber} for ${destination}: ${error.message}`,
        context,
        error.stack,
      );
    }
  }

  /**
   * Message handler
   * @param record - The record to handle
   * @param sequenceNumber - The sequence number of the message
   * @returns Object indicating if message was processed or filtered
   */
  public async handleMessage(
    record: CombinedDtoWithIndex,
    sequenceNumber: string | Array<string> | undefined,
  ): Promise<{ processed: boolean; reason?: string }> {
    const contextLog: JobsLogContext = {
      method: 'handleMessage',
      service: 'DaprServiceApi',
    };
    incrementPendingMessageCount();
    try {
      // Since we did the checkPayloadConsistency before in ebenthub shift tracking and shift tracking details services,
      // We can skip it here
      // If (!checkPayloadConsistency(this.customLogger, contextLog, record))
      //   Return;

      const { __source_table: sourceTable, __op: operation } = record;

      if (!sourceTable) return { processed: false, reason: 'no_source_table' };

      // Use fan-out aware approach: each destination maintains its own queue.
      // For append step we derive all destinations and enqueue accordingly.
      const destinations =
        this.mappingService.getDestinationsForSource(sourceTable);
      const mappedOutputs =
        destinations.length > 1
          ? this.mappingService.mapAllData(sourceTable, record, this.plantList)
          : [this.mappingService.mapData(sourceTable, record, this.plantList)];

      const newRecords = mappedOutputs
        .filter(({ mappedData }) =>
          checkPlantConsistency(this.customLogger, mappedData, this.plantList),
        )
        .map(({ mappedData, destination, ingestionEventTracking }) => ({
          destination,
          ingestionEventTracking,
          mappedData,
          operation,
          sourceTable,
        }));
      if (newRecords.length === 0)
        return { processed: false, reason: 'plant_consistency_filtered' };

      // Process sequentially to maintain order
      for (const recordP of newRecords) {
        await this.processMessage(recordP, sequenceNumber);
      }

      return { processed: true };
    } catch (error) {
      this.customLogger.error(
        `Error handling Message: ${error.message}`,
        contextLog,
        error.stack,
      );
      return { processed: false, reason: 'error' };
    } finally {
      decrementPendingMessageCount();
    }
  }
}

