  public async receiveEventActionsOnProd(
    @Req() request: Request,
  ): Promise<string> {
    if (await this.eventhubSdkConfigService.useEventhubSDK()) {
      return 'OK USE EVENT HUB SDK';
    }
    const event = request.body as Record<string, unknown>;
    // Filter here as well for Dapr bindings path
    if (
      !['LOW', 'HIGH', 'NORMAL', 'SPECIAL', 'HOUR_ACTION'].includes(
        event?.['ACTION'] as string,
      )
    ) {
      return 'IGNORED';
    }
    return this.processStandardEvent(request, 'receiveEventActionsOnProd');
  }

  @Post(bindings.bindingChangeTools)
  public async receiveEventChangeTools(
    @Req() request: Request,
  ): Promise<string> {
    if (await this.eventhubSdkConfigService.useEventhubSDK()) {
      return 'OK USE EVENT HUB SDK';
    }
    return this.processStandardEvent(request, 'receiveEventChangeTools');
