  ): Promise<string> {
    if (await this.eventhubSdkConfigService.useEventhubSDK()) {
      return 'OK USE EVENT HUB SDK';
    }
    return this.processStandardEvent(request, 'receiveEventRoutingPrt');
  }

  @Post(bindings.topicPlants)
  public async initPlant(@Req() request: Request): Promise<string> {
    const context = DaprController.createLogContext('initPlant');
    try {
      const data = request.body;
      await this.subscribeMessageService.handleMessage(data);
      await this.daprService.initializePlant();
      await this.daprServiceApi.initializePlant();
      this.customLogger.debug(`Updated Plants List`, context);
      return 'OK';
    } catch (error) {
      this.customLogger.error(
        `Error processing event: ${error.message}`,
        context,
        error.stack,
      );
      throw error;
    }
  }

  @Post(bindings.bindingCadenceConfig)
  public async receiveEventCadenceConfig(
    @Req() request: Request,
  ): Promise<string> {
    if (await this.eventhubSdkConfigService.useEventhubSDK()) {
      return 'OK USE EVENT HUB SDK';
    }
    return this.processStandardEvent(request, 'receiveEventCadenceConfig');
  }

  @Post(bindings.bindingAssemblyLineConfig)
  public async receiveEventAssemblyLineConfig(
    @Req() request: Request,
  ): Promise<string> {
    if (await this.eventhubSdkConfigService.useEventhubSDK()) {
      return 'OK USE EVENT HUB SDK';
    }
    return this.processStandardEvent(request, 'receiveEventAssemblyLineConfig');
  }
}

