/**
 * Helper function to track both event processing duration and event processed metrics
 * @param startTime start time
 * @param status  status of processing
 * @param plantCode plant code
 * @param topicName topic name
 * @param partitionId partition ID (optional)
 */
function trackEventTelemetry(
  startTime: number,
  status: PROCESSING_STATUS,
  plantCode: string,
  topicName: string,
  partitionId?: string,
): void {
  const duration = Date.now() - startTime;
  telemetryMetrics.trackEventProcessingDuration(
    duration,
    status,
    plantCode,
    topicName,
    partitionId,
  );
  telemetryMetrics.trackEventProcessed(
    status,
    plantCode,
    topicName,
    partitionId,
  );
}

@Injectable()
export class EventHubSdkActionsOnProductionService
  implements OnModuleInit, OnModuleDestroy
{
  private static createLogContext(
    method: string,
    plant?: number,
    object?: string,
    userId?: string,
  ): JobsLogContext {
    return {
      method,
      object,
      plant,
      service: EventHubSdkActionsOnProductionService.name,
      userId,
    };
  }

  private clients: EventHubClients | null = null;

  private subscription: Subscription | null = null;

  private partitionInfo: Map<string, PartitionInfo> | null = null;

  private readonly shutdownState: ShutdownState = createShutdownState();

  private allowedPlantsResources: string | undefined = undefined;

  public constructor(
    private readonly configService: EventhubSdkConfigService,
    private readonly daprService: DaprServiceApi,
    private readonly logger: AppLogger,
    private readonly ingestionPolicyConfigService: IngestionPolicyConfigService,
  ) {}

  public async onModuleInit(): Promise<void> {
    await this.initialize();
  }

  public async onModuleDestroy(): Promise<void> {
    await this.cleanup();
  }

  private async initialize(): Promise<void> {
    const context =
      EventHubSdkActionsOnProductionService.createLogContext('initialize');

    try {
      // Check if we should skip initialization
      const useEventhubSDK = await this.configService.useEventhubSDK();

      if (!useEventhubSDK) {
        this.logger.warn(
          `[actionsOnProd] Skipping EventHub SDK initialization - useEventhubSDK: ${useEventhubSDK}`,
          context,
        );
        return;
      }
      this.logger.log('Initializing actionsOnProd EventHub service', context);

      // Get App config allowed plants and resources
      this.allowedPlantsResources =
        await this.ingestionPolicyConfigService.appConfigAllowedPlantResources();

      // Get EventHub configuration using the helper method
      const eventHubConfig = this.configService.getActionOnProdConfig();

      // Initialize EventHub clients
      this.clients = await initializeEventHub(eventHubConfig, this.logger);

      // Create message processor
      const enhancedProcessor = this.createMessageProcessor();

      // Wrap enhanced processor to match MessageProcessor interface
      const processor: MessageProcessor = {
        processMessage: async (message, sequenceNumber, partitionId) => {
          await enhancedProcessor.processMessage(
            message,
            sequenceNumber,
            partitionId,
          );
        },
      };
      // Configure error recovery
      const errorRecoveryConfig = {
        enabled: true,
        eventHubConfig,
      };

      // Subscribe to EventHub with enhanced features
      const subscriptionResult = subscribeToEventHub(processor, {
        checkpointConfig: {
          ...eventHubConfig,
          checkpointInterval:
            this.configService.actionsOnProdCheckpointInterval,
        },
        clients: this.clients,
        errorRecoveryConfig,
        logger: this.logger,
        processingConfig: {
          serviceName: 'EventHubActionsOnProdService',
          topicName: 'actions-on-prod',
        },
        shutdownState: this.shutdownState,
        subscriptionConfig: {
          enableCheckpointing: true,
          maxBatchSize: 1,
        },
      });

      this.subscription = subscriptionResult.subscription;
      this.partitionInfo = subscriptionResult.partitionInfo;

      this.logger.log(
        'Enhanced actionsOnProd EventHub service initialized successfully',
        context,
      );
    } catch (error) {
      this.logger.error(
        `Failed to initialize Enhanced actionsOnProd EventHub service: ${error.message}`,
        context,
        error instanceof Error ? error : new Error(String(error)),
      );
      throw error;
    }
  }

  private async cleanup(): Promise<void> {
    const context =
      EventHubSdkActionsOnProductionService.createLogContext('cleanup');

    try {
      this.logger.log(
        'Cleaning up Enhanced actionsOnProd EventHub service',
        context,
      );

      // Set shutdown state to true
      this.shutdownState.value = true;

      // Unsubscribe from EventHub
      if (this.subscription) {
        await unsubscribeFromEventHub(
          this.subscription,
          'EventHubActionsOnProdService',
          this.logger,
        );
        this.subscription = null;
      }

      // Perform final checkpoints
      if (this.clients && this.partitionInfo) {
        await performFinalCheckpoints(
          this.clients.checkpointStore,
          {
            checkpointInterval:
              this.configService.actionsOnProdCheckpointInterval,
            consumerGroup: this.configService.actionsOnProdConsumerGroup,
            eventHubName: this.configService.actionsOnProdEventHubName,
            eventHubNamespace:
              this.configService.actionsOnProdEventHubNamespace,
          },
          this.partitionInfo,
          this.logger,
        );
      }

      // Clean up EventHub clients
      if (this.clients) {
        await cleanupEventHub(this.clients, this.logger);
        this.clients = null;
      }

      this.partitionInfo = null;

      this.logger.log(
        'Enhanced actionsOnProd EventHub service cleanup completed',
        context,
      );
    } catch (error) {
      this.logger.error(
        `Error during Enhanced actionsOnProd EventHub service cleanup: ${error.message}`,
        context,
        error instanceof Error ? error : new Error(String(error)),
      );
    }
  }

  /**
   * Create message processor specific to actionsOnProd with validation and masking
   * @returns MessageProcessor configured for actionsOnProd processing
   */
  private createMessageProcessor(): EnhancedMessageProcessor {
    // Parse the App Config string once at processor creation
    const { allowAll, allowedPlantsAndResources } = buildAllowedPlantsResources(
      this.allowedPlantsResources,
    );
    return {
      processMessage: async (
        message: CombinedDtoWithIndex,
        sequenceNumber: string,
        partitionId?: string,
      ): Promise<ProcessingResult | void> => {
        const startTime = Date.now();
        const plantCode = String(message.PLANT);
        const topicName = 'actions-on-prod';
        if (
          !checkPayloadConsistency(
            this.logger,
            EventHubSdkActionsOnProductionService.createLogContext(
              'validateMessage',
            ),
            message,
          )
        ) {
          trackEventTelemetry(
            startTime,
            PROCESSING_STATUS.INVALID,
            plantCode,
            topicName,
            partitionId,
          );

          return undefined;
        }

        // Unified filter: Only process if ACTION is LOW, HIGH, SPECIAL for ACTIONS_ON_PROD
        const sourceTable = (message as Record<string, unknown>)?.[
          '__source_table'
        ];
        const actionRaw = (message as Record<string, unknown>)?.['ACTION'];
        let action = '';

        if (typeof actionRaw === 'string') {
          action = actionRaw;
        } else if (
          typeof actionRaw === 'number' ||
          typeof actionRaw === 'boolean'
        ) {
          action = String(actionRaw);
        }

        if (
          sourceTable === 'ACTIONS_ON_PROD' &&
          !['LOW', 'HIGH', 'NORMAL', 'SPECIAL', 'HOUR_ACTION'].includes(action)
        ) {
          return undefined;
        }
        // If config empty or universal "*" → allow all
        if (allowAll || Object.keys(allowedPlantsAndResources).length === 0) {
          const result = await this.daprService.handleMessage(
            message,
            sequenceNumber,
          );
          const status = result.processed
            ? PROCESSING_STATUS.PROCESSED
            : PROCESSING_STATUS.FILTERED;

          trackEventTelemetry(
            startTime,
            status,
            plantCode,
            topicName,
            partitionId,
          );

          return {
            plantCode,
            status: result.processed ? 'processed' : 'filtered',
          };
        }
        const plantResources = allowedPlantsAndResources[message.PLANT];
        // Early exit if plant not authorized

        if (!plantResources) {
          trackEventTelemetry(
            startTime,
            PROCESSING_STATUS.FILTERED,
            plantCode,
            topicName,
            partitionId,
          );
          return { plantCode, status: 'filtered' };
        }
        // Normalize PLC_ID to string for safe comparison

        const plcId = String(message.PLC_ID ?? '');
        // If plant allows all resources via ["*"], skip resource check
        if (!plantResources.includes('*') && !plantResources.includes(plcId)) {
          trackEventTelemetry(
            startTime,
            PROCESSING_STATUS.FILTERED,
            plantCode,
            topicName,
            partitionId,
          );

          return { plantCode, status: 'filtered' };
        }

        // Both checks passed → process message
        const result = await this.daprService.handleMessage(
          message,
          sequenceNumber,
        );
        const status = result.processed
          ? PROCESSING_STATUS.PROCESSED
          : PROCESSING_STATUS.FILTERED;

        trackEventTelemetry(
          startTime,
          status,
          plantCode,
          topicName,
          partitionId,
        );

        return {
          plantCode,
          status: result.processed ? 'processed' : 'filtered',
        };
      },
    };
  }
}

