        'Enhanced change-tools EventHub service initialized successfully',
        context,
      );
    } catch (error) {
      this.logger.error(
        `Failed to initialize Enhanced change-tools EventHub service: ${error.message}`,
        context,
        error instanceof Error ? error : new Error(String(error)),
      );
      throw error;
    }
  }

  private async cleanup(): Promise<void> {
    const context = EventHubSdkChangeToolsService.createLogContext('cleanup');

    try {
      this.logger.log(
        'Cleaning up Enhanced change-tools EventHub service',
        context,
      );

      // Set shutdown state to true
      this.shutdownState.value = true;

      // Unsubscribe from EventHub
      if (this.subscription) {
        await unsubscribeFromEventHub(
          this.subscription,
          'EventHubChangeToolsEnhancedService',
          this.logger,
        );
        this.subscription = null;
      }

      // Perform final checkpoints
      if (this.clients && this.partitionInfo) {
        await performFinalCheckpoints(
          this.clients.checkpointStore,
          {
            checkpointInterval:
              this.configService.changeToolsCheckpointInterval,
            consumerGroup: this.configService.changeToolsConsumerGroup,
            eventHubName: this.configService.eventHubChangeToolsName,
            eventHubNamespace: this.configService.eventHubChangeToolsNamespace,
          },
          this.partitionInfo,
          this.logger,
        );
      }

      // Clean up EventHub clients
      if (this.clients) {
        await cleanupEventHub(this.clients, this.logger);
        this.clients = null;
      }

      this.partitionInfo = null;

      this.logger.log(
        'Enhanced change tools EventHub service cleanup completed',
        context,
      );
    } catch (error) {
      this.logger.error(
        `Error during Enhanced change tools EventHub service cleanup: ${error.message}`,
        context,
        error instanceof Error ? error : new Error(String(error)),
      );
    }
  }

  /**
   * Create message processor specific to change tools with validation and masking
   * @returns MessageProcessor configured for change tools processing
   */
  private createMessageProcessor(): EnhancedMessageProcessor {
    // Parse the App Config string once at processor creation
    const { allowAll, allowedPlantsAndResources } = buildAllowedPlantsResources(
      this.allowedPlantsResources,
    );
    return {
      processMessage: async (
        message: CombinedDtoWithIndex,
        sequenceNumber: string,
        partitionId?: string,
      ): Promise<ProcessingResult | void> => {
        const startTime = Date.now();
        const plantCode = String(message.PLANT);
        const topicName = 'change-tools';
        if (
          !checkPayloadConsistency(
            this.logger,
            EventHubSdkChangeToolsService.createLogContext('validateMessage'),
            message,
          )
        ) {
          trackEventTelemetry(
            startTime,
            PROCESSING_STATUS.INVALID,
            plantCode,
            topicName,
            partitionId,
          );

          return undefined;
        }

        // If config empty or universal "*" → allow all
        if (allowAll || Object.keys(allowedPlantsAndResources).length === 0) {
          const result = await this.daprService.handleMessage(
            message,
            sequenceNumber,
          );
          const status = result.processed
            ? PROCESSING_STATUS.PROCESSED
            : PROCESSING_STATUS.FILTERED;

          trackEventTelemetry(
            startTime,
            status,
            plantCode,
            topicName,
            partitionId,
          );

          return {
            plantCode,
            status: result.processed ? 'processed' : 'filtered',
          };
        }
        const plantResources = allowedPlantsAndResources[message.PLANT];
        // Early exit if plant not authorized

        if (!plantResources) {
          trackEventTelemetry(
            startTime,
            PROCESSING_STATUS.FILTERED,
            plantCode,
            topicName,
            partitionId,
          );
          return { plantCode, status: 'filtered' };
        }
        // Normalize PLC_ID to string for safe comparison

        const plcId = String(message.PLC_ID ?? '');
        // If plant allows all resources via ["*"], skip resource check
        if (!plantResources.includes('*') && !plantResources.includes(plcId)) {
          trackEventTelemetry(
            startTime,
            PROCESSING_STATUS.FILTERED,
            plantCode,
            topicName,
            partitionId,
          );

          return { plantCode, status: 'filtered' };
        }

        const result = await this.daprService.handleMessage(
          message,
          sequenceNumber,
        );
        const status = result.processed
          ? PROCESSING_STATUS.PROCESSED
          : PROCESSING_STATUS.FILTERED;

        trackEventTelemetry(
          startTime,
          status,
          plantCode,
          topicName,
          partitionId,
        );

        return {
          plantCode,
          status: result.processed ? 'processed' : 'filtered',
        };
      },
    };
  }
}

import { EventHubProducerClient, EventData } from '@azure/event-hubs';
import { DefaultAzureCredential } from '@azure/identity';
