import { AppLogger } from '@/common/logger/app-logger';
import { EventhubSdkConfigService } from '@/config/eventhub-sdk/eventhub-sdk-config.service';
import { ShiftTrackingDtl } from '@/modules/shift-tracking/shift-tracking-dtl.entity';
import { ShiftTrackingStatus } from '@/modules/shift-tracking-status/shift-tracking-status.entity';

export interface EventHubMessage {
  plant: number;
  payload:
    | QueryDeepPartialEntity<ShiftTrackingDtl>
    | QueryDeepPartialEntity<ShiftTrackingStatus>;
  destinationTable: 'shift_tracking_dtl' | 'shift_tracking_status';
}

@Injectable()
export class EventHubProducerService implements OnModuleInit, OnModuleDestroy {
  /**
   * Group messages by plant to ensure they use correct partition keys
   * @param messages - The messages to group
   * @returns A map of plant to its corresponding messages
   */

  private static groupMessagesByPlant(
    messages: Array<EventHubMessage>,
  ): Map<number, Array<EventHubMessage>> {
    const grouped = new Map<number, Array<EventHubMessage>>();

    for (const message of messages) {
      let array = grouped.get(message.plant);
      if (!array) {
        array = [];
        grouped.set(message.plant, array);
      }
      array.push(message);
    }

    return grouped;
  }

  private producerClient: EventHubProducerClient | undefined;

  private isShuttingDown = false;

  public constructor(
    private readonly logger: AppLogger,
    private readonly eventHubConfig: EventhubSdkConfigService,
  ) {}

  public async onModuleInit(): Promise<void> {
    const context = {
      method: 'onModuleInit',
      service: EventHubProducerService.name,
    };

    try {
      const connectionString = this.eventHubConfig.producerConnectionString;
      const eventHubNamespace = this.eventHubConfig.producerEventHubNamespace;
      const eventHubName = this.eventHubConfig.producerEventHubName;

      // Use connection string if provided, otherwise use Azure AD authentication
      if (connectionString) {
        this.logger.log(
          `Initializing Event Hub producer with connection string for Event Hub: ${eventHubName}`,
          context,
        );
        this.producerClient = new EventHubProducerClient(
          connectionString,
          eventHubName,
        );
      } else {
        if (!eventHubNamespace) {
          throw new Error(
            'Event Hub namespace or connection string must be configured',
          );
        }

        this.logger.log(
          `Initializing Event Hub producer with Azure AD for ${eventHubNamespace}/${eventHubName}`,
          context,
        );

        const credential = new DefaultAzureCredential();
        this.producerClient = new EventHubProducerClient(
          eventHubNamespace,
          eventHubName,
          credential,
        );
      }

      this.logger.log(
        `Event Hub producer initialized successfully for topic: ${eventHubName}`,
        context,
      );
      this.logger.log(`Using namespace:, Event Hub: ${eventHubName}`, context);
    } catch (error) {
      this.logger.error(
        `Failed to initialize Event Hub producer: ${error instanceof Error ? error.message : String(error)}`,
        context,
        error instanceof Error ? error : new Error(String(error)),
      );
      throw error;
    }
  }

  public async onModuleDestroy(): Promise<void> {
    const context = {
      method: 'onModuleDestroy',
      service: EventHubProducerService.name,
    };

    this.isShuttingDown = true;

    try {
      // Close the producer client
      if (this.producerClient) {
        await this.producerClient.close();
        this.logger.log('Event Hub producer closed successfully', context);
      }
    } catch (error) {
      this.logger.error(
        `Error during Event Hub producer shutdown: ${error instanceof Error ? error.message : String(error)}`,
        context,
        error instanceof Error ? error : new Error(String(error)),
      );
    }
  }

  /**
   * Send messages to Event Hub as a batch
   * @param messages - The list of messages to send
   * @param failureTimestamp - The timestamp to include in message properties for tracking failures
   */
  public async sendMessages(
    messages: Array<EventHubMessage>,
    failureTimestamp: string,
  ): Promise<void> {
    const context = {
      method: 'sendMessages',
      service: EventHubProducerService.name,
    };
    if (this.isShuttingDown) {
      this.logger.warn(
        'Cannot send messages: Producer is shutting down',
        context,
      );
      return;
    }

    if (!messages || messages.length === 0) {
      this.logger.warn('No messages provided to send', context);
      return;
    }

    if (!this.producerClient) {
      throw new Error('Producer client not initialized');
    }

    try {
      // Group messages by plant for batch sending
      const messagesByPlant =
        EventHubProducerService.groupMessagesByPlant(messages);

      // Send all plant batches in parallel
      const sendPromises = [...messagesByPlant.entries()].map(
        async ([plant, plantMessages]) => {
          const eventDataList: Array<EventData> = plantMessages.map(
            (message) => ({
              body: message.payload,
              properties: {
                plant: message.plant,
                timestamp: failureTimestamp,
                destinationTable: message.destinationTable,
              },
            }),
          );

          this.logger.debug(
            `Sending ${eventDataList.length} messages to Event Hub for plant ${plant}`,
            context,
          );
          if (this.producerClient) {
            await this.producerClient.sendBatch(eventDataList, {
              partitionKey: plant.toString(),
            });
          }

          this.logger.debug(
            `Successfully sent ${eventDataList.length} messages for plant ${plant}`,
            context,
          );
        },
      );

      const results = await Promise.allSettled(sendPromises);

      // Check for failures and log them
      const failures = results.filter(
        (result): result is PromiseRejectedResult =>
          result.status === 'rejected',
      );
      if (failures.length > 0) {
        const errorMessage = failures.map((f) => f.reason).join('; ');
        throw new Error(
          `Failed to send ${failures.length} of ${results.length} plant batches: ${errorMessage}`,
        );
      }
    } catch (error) {
      const errorDetails =
        error instanceof Error
          ? {
              message: error.message,
              name: error.name,
            }
          : String(error);

      this.logger.error(
        `Failed to send batch of ${messages.length} messages: ${JSON.stringify(errorDetails)}`,
        context,
        error instanceof Error ? error : new Error(String(error)),
      );
      throw error;
    }
  }
}

