  unsubscribeFromEventHub,
} from '@/helpers/eventhub-functions/subscription';
import { checkPayloadConsistency } from '@/helpers/validations/check-payload-consistency';

/**
 * Tracks telemetry for processed / filtered / invalid events.
 * @param startTime Start timestamp used to compute duration.
 * @param status Processing status to report.
 * @param plantCode Plant identifier attached to telemetry.
 * @param topicName Logical topic name for telemetry context.
 * @param partitionId EventHub partition id when available.
 */
function trackEventTelemetry(
  startTime: number,
  status: PROCESSING_STATUS,
  plantCode: string,
  topicName: string,
  partitionId?: string,
): void {
  const duration = Date.now() - startTime;
  telemetryMetrics.trackEventProcessingDuration(
    duration,
    status,
    plantCode,
    topicName,
    partitionId,
  );
  telemetryMetrics.trackEventProcessed(
    status,
    plantCode,
    topicName,
    partitionId,
  );
}

@Injectable()
export class EventHubSdkRoutingPrtService
  implements OnModuleInit, OnModuleDestroy
{
  private static createLogContext(
    method: string,
    plant?: number,
    object?: string,
    userId?: string,
  ): JobsLogContext {
    return {
      method,
      object,
      plant,
      service: EventHubSdkRoutingPrtService.name,
      userId,
    };
  }

  private clients: EventHubClients | null = null;

  private subscription: Subscription | null = null;

  private partitionInfo: Map<string, PartitionInfo> | null = null;

  private readonly shutdownState: ShutdownState = createShutdownState();

  private allowedPlantsResources: string | undefined = undefined;

  public constructor(
    private readonly configService: EventhubSdkConfigService,
    private readonly daprService: DaprServiceApi,
    private readonly logger: AppLogger,
    private readonly ingestionPolicyConfigService: IngestionPolicyConfigService,
  ) {}

  public async onModuleInit(): Promise<void> {
    await this.initialize();
  }

  public async onModuleDestroy(): Promise<void> {
    await this.cleanup();
  }

  private async initialize(): Promise<void> {
    const context = EventHubSdkRoutingPrtService.createLogContext('initialize');
    try {
      const useEventhubSDK = await this.configService.useEventhubSDK();
      if (!useEventhubSDK) {
        this.logger.warn(
          `[routingPrt] Skipping EventHub SDK initialization - useEventhubSDK: ${useEventhubSDK}`,
          context,
        );
        return;
      }
      this.logger.log('Initializing routingPrt EventHub service', context);
      this.allowedPlantsResources =
        await this.ingestionPolicyConfigService.appConfigAllowedPlantResources();
      const eventHubConfig = this.configService.getRoutingPrtConfig();
      this.clients = await initializeEventHub(eventHubConfig, this.logger);
      const enhancedProcessor = this.createMessageProcessor();
      const processor: MessageProcessor = {
        processMessage: async (message, sequenceNumber, partitionId) => {
          await enhancedProcessor.processMessage(
            message,
            sequenceNumber,
            partitionId,
          );
        },
      };
      const errorRecoveryConfig = {
        enabled: true,
        eventHubConfig,
      };
      const subscriptionResult = subscribeToEventHub(processor, {
        checkpointConfig: {
          ...eventHubConfig,
          checkpointInterval: this.configService.routingPrtCheckpointInterval,
        },
        clients: this.clients,
        errorRecoveryConfig,
        logger: this.logger,
        processingConfig: {
          serviceName: 'EventHubRoutingPrtService',
          topicName: 'routingPrt',
        },
        shutdownState: this.shutdownState,
        subscriptionConfig: {
          maxBatchSize: 1,
          enableCheckpointing: true,
        },
      });
      this.subscription = subscriptionResult.subscription;
      this.partitionInfo = subscriptionResult.partitionInfo;
      this.logger.log(
        'Enhanced routingPrt EventHub service initialized successfully',
        context,
      );
    } catch (error) {
      this.logger.error(
        `Failed to initialize Enhanced routingPrt EventHub service: ${error.message}`,
        context,
        error instanceof Error ? error : new Error(String(error)),
      );
      throw error;
    }
  }

  private async cleanup(): Promise<void> {
    const context = EventHubSdkRoutingPrtService.createLogContext('cleanup');
    try {
      this.logger.log(
        'Cleaning up Enhanced routingPrt EventHub service',
        context,
      );
      // Set shutdown state to true
      this.shutdownState.value = true;

      // Unsubscribe from EventHub
      if (this.subscription) {
        await unsubscribeFromEventHub(
          this.subscription,
          'EventHubRoutingPrtService',
          this.logger,
        );
        this.subscription = null;
      }

      // Perform final checkpoints
      if (this.clients && this.partitionInfo) {
        await performFinalCheckpoints(
          this.clients.checkpointStore,
          {
            consumerGroup: this.configService.routingPrtConsumerGroup,
            eventHubName: this.configService.routingPrtEventHubName,
            eventHubNamespace: this.configService.routingPrtEventHubNamespace,
            checkpointInterval: this.configService.routingPrtCheckpointInterval,
          },
          this.partitionInfo,
          this.logger,
        );
      }

      // Clean up EventHub clients
      if (this.clients) {
        await cleanupEventHub(this.clients, this.logger);
        this.clients = null;
      }
      this.partitionInfo = null;
      this.logger.log(
        'Enhanced routingPrt EventHub service cleanup completed',
        context,
      );
    } catch (error) {
      this.logger.error(
        `Error during Enhanced routingPrt EventHub service cleanup: ${error.message}`,
        context,
        error instanceof Error ? error : new Error(String(error)),
      );
    }
  }

  private createMessageProcessor(): EnhancedMessageProcessor {
    const { allowAll, allowedPlantsAndResources } = buildAllowedPlantsResources(
      this.allowedPlantsResources,
    );
    return {
      processMessage: async (
        message: CombinedDtoWithIndex,
        sequenceNumber: string,
        partitionId?: string,
      ): Promise<ProcessingResult | void> => {
        const startTime = Date.now();
        const plantCode = String(message.PLANT);
        const topicName = 'routingPrt';

        if (
          !checkPayloadConsistency(
            this.logger,
            EventHubSdkRoutingPrtService.createLogContext('validateMessage'),
            message,
          )
        ) {
          trackEventTelemetry(
            startTime,
            PROCESSING_STATUS.INVALID,
            plantCode,
            topicName,
            partitionId,
          );
          return undefined;
        }

        if (allowAll || Object.keys(allowedPlantsAndResources).length === 0) {
          const result = await this.daprService.handleMessage(
            message,
            sequenceNumber,
          );
          const status = result.processed
            ? PROCESSING_STATUS.PROCESSED
            : PROCESSING_STATUS.FILTERED;
          trackEventTelemetry(
            startTime,
            status,
            plantCode,
            topicName,
            partitionId,
          );
          return {
            status: result.processed ? 'processed' : 'filtered',
            plantCode,
          };
        }

        const plantResources = allowedPlantsAndResources[message.PLANT];
        if (!plantResources) {
          trackEventTelemetry(
            startTime,
            PROCESSING_STATUS.FILTERED,
            plantCode,
            topicName,
            partitionId,
          );
          return { status: 'filtered', plantCode };
        }

        const result = await this.daprService.handleMessage(
          message,
          sequenceNumber,
        );
        const status = result.processed
          ? PROCESSING_STATUS.PROCESSED
          : PROCESSING_STATUS.FILTERED;
        trackEventTelemetry(
          startTime,
          status,
          plantCode,
          topicName,
          partitionId,
        );
        return {
          status: result.processed ? 'processed' : 'filtered',
          plantCode,
        };
      },
    };
  }
}

