@Injectable()
export class EventHubSdkShiftTrackingStatusService
  implements OnModuleInit, OnModuleDestroy
{
  private static createLogContext(
    method: string,
    plant?: number,
    object?: string,
    userId?: string,
  ): JobsLogContext {
    return {
      method,
      object,
      plant,
      service: EventHubSdkShiftTrackingStatusService.name,
      userId,
    };
  }

  private clients: EventHubClients | null = null;

  private subscription: Subscription | null = null;

  private partitionInfo: Map<string, PartitionInfo> | null = null;

  private readonly shutdownState: ShutdownState = createShutdownState();

  private allowedPlantsResources: string | undefined = undefined;

  private readonly enableTelemetry =
    this.telemetryConfigService.enableTelemetry;

  public constructor(
    private readonly configService: EventhubSdkConfigService,
    private readonly daprService: DaprServiceApi,
    private readonly logger: AppLogger,
    private readonly ingestionPolicyConfigService: IngestionPolicyConfigService,
    private readonly telemetryConfigService: TelemetryConfigService,
  ) {
    // TelemetryMetrics is initialized in main.ts before NestJS bootstrap
    // No initialization needed here - use the singleton directly
  }

  public async onModuleInit(): Promise<void> {
    await this.initialize();
  }

  public async onModuleDestroy(): Promise<void> {
    await this.cleanup();
  }

  private async initialize(): Promise<void> {
    const context =
      EventHubSdkShiftTrackingStatusService.createLogContext('initialize');

    try {
      // Check if we should skip initialization
      const useEventhubSDK = await this.configService.useEventhubSDK();

      if (!useEventhubSDK) {
        this.logger.warn(
          `[shift tracking status] Skipping EventHub SDK initialization - useEventhubSDK: ${useEventhubSDK}`,
          context,
        );
        return;
      }

      this.logger.log(
        'Initializing  shiftTrackingStatus EventHub service',
        context,
      );

      // Get App config allowed plants and resources

      this.allowedPlantsResources =
        await this.ingestionPolicyConfigService.appConfigAllowedPlantResources();

      // Get EventHub configuration using the helper method
      const eventHubConfig = this.configService.getShiftTrackingStatusConfig();

      // Initialize EventHub clients
      this.clients = await initializeEventHub(eventHubConfig, this.logger);

      // Create message processor
      const enhancedProcessor = this.createMessageProcessor();

      // Wrap enhanced processor to match MessageProcessor interface
      const processor: MessageProcessor = {
        processMessage: async (message, sequenceNumber, partitionId) => {
