  /**
   * Create message processor specific to shift tracking with validation and masking
   * @returns EnhancedMessageProcessor configured for shift tracking processing
   */
  private createMessageProcessor(): EnhancedMessageProcessor {
    // Parse the App Config string once at processor creation
    const { allowAll, allowedPlantsAndResources } = buildAllowedPlantsResources(
      this.allowedPlantsResources,
    );
    return {
      processMessage: async (
        message: CombinedDtoWithIndex,
        sequenceNumber: string,
        partitionId?: string,
      ): Promise<ProcessingResult | void> => {
        const startTime = Date.now();
        const plantCode = String(message.PLANT);

        if (
          !checkPayloadConsistency(
            this.logger,
            EventHubSdkShiftTrackingStatusService.createLogContext(
              'validateMessage',
            ),
            message,
          )
        ) {
          // Track invalid payload
          const duration = Date.now() - startTime;
          if (this.enableTelemetry) {
            telemetryMetrics.trackEventProcessingDuration(
              duration,
              PROCESSING_STATUS.INVALID,
              plantCode,
              'shift-tracking-status',
              partitionId,
            );
            telemetryMetrics.trackEventProcessed(
              PROCESSING_STATUS.INVALID,
              plantCode,
              'shift-tracking-status',
              partitionId,
            );
          }
          return undefined;
        }

        // If config empty or universal "*" → allow all
        if (allowAll || Object.keys(allowedPlantsAndResources).length === 0) {
          const result = await this.daprService.handleMessage(
            message,
            sequenceNumber,
          );
          const duration = Date.now() - startTime;

          if (result.processed) {
            if (this.enableTelemetry) {
              telemetryMetrics.trackEventProcessingDuration(
                duration,
                PROCESSING_STATUS.PROCESSED,
                plantCode,
                'shift-tracking-status',
                partitionId,
              );
              telemetryMetrics.trackEventProcessed(
                PROCESSING_STATUS.PROCESSED,
                plantCode,
                'shift-tracking-status',
                partitionId,
              );
            }
            return { plantCode, status: 'processed' };
          }
          // Filtered by plant consistency or other internal logic
          if (this.enableTelemetry) {
            telemetryMetrics.trackEventProcessingDuration(
              duration,
              PROCESSING_STATUS.FILTERED,
              plantCode,
              'shift-tracking-status',
              partitionId,
            );
            telemetryMetrics.trackEventProcessed(
              PROCESSING_STATUS.FILTERED,
              plantCode,
              'shift-tracking-status',
              partitionId,
            );
          }
          return { plantCode, status: 'filtered' };
        }
        const plantResources = allowedPlantsAndResources[message.PLANT];
        // Early exit if plant not authorized

        if (!plantResources) {
          const duration = Date.now() - startTime;

          telemetryMetrics.trackEventProcessingDuration(
            duration,
            PROCESSING_STATUS.FILTERED,
            plantCode,
            'shift-tracking-status',
            partitionId,
          );
          telemetryMetrics.trackEventProcessed(
            PROCESSING_STATUS.FILTERED,
            plantCode,
            'shift-tracking-status',
            partitionId,
          );
          return { plantCode, status: 'filtered' };
        }
        // Normalize PLC_ID to string for safe comparison

        const plcId = String(message.PLC_ID ?? '');
        // If plant allows all resources via ["*"], skip resource check
        if (!plantResources.includes('*') && !plantResources.includes(plcId)) {
          const duration = Date.now() - startTime;
          if (this.enableTelemetry) {
            telemetryMetrics.trackEventProcessingDuration(
              duration,
              PROCESSING_STATUS.FILTERED,
              plantCode,
              'shift-tracking-status',
              partitionId,
            );
            telemetryMetrics.trackEventProcessed(
              PROCESSING_STATUS.FILTERED,
              plantCode,
              'shift-tracking-status',
              partitionId,
            );
          }
          return { plantCode, status: 'filtered' };
        }
        // Both checks passed → process message
        const result = await this.daprService.handleMessage(
          message,
          sequenceNumber,
        );
        const duration = Date.now() - startTime;

        if (result.processed) {
          if (this.enableTelemetry) {
            telemetryMetrics.trackEventProcessingDuration(
              duration,
              PROCESSING_STATUS.PROCESSED,
              plantCode,
              'shift-tracking-status',
              partitionId,
            );
            telemetryMetrics.trackEventProcessed(
              PROCESSING_STATUS.PROCESSED,
              plantCode,
              'shift-tracking-status',
              partitionId,
            );
          }
          return { plantCode, status: 'processed' };
        }
        // Filtered by plant consistency or other internal logic
        if (this.enableTelemetry) {
          telemetryMetrics.trackEventProcessingDuration(
            duration,
            PROCESSING_STATUS.FILTERED,
            plantCode,
            'shift-tracking-status',
            partitionId,
          );
          telemetryMetrics.trackEventProcessed(
            PROCESSING_STATUS.FILTERED,
            plantCode,
            'shift-tracking-status',
            partitionId,
