        'plant',
        'resourceId',
        'shiftCode',
      ]);
      AssemblyLineConfigService.trackSqlMetrics(payload.plant, sqlStartTime);
    } catch (error) {
      this.customLogger.error(
        `Error upserting (insert or update) AssemblyLineConfig in database: ${AssemblyLineConfigService.getErrorMessage(error)}`,
        context,
      );
    }
  }

