      'readSnapshot',
      payload?.plant,
      payload?.resourceId,
    );
    if (this.shouldSkipPayload(payload, context)) {
      return;
    }
    try {
      const sqlStartTime = Date.now();
      const { plant, resourceId, shiftCode, ...data } = payload;
      await this.repo.manager.transaction(
        async (transactionalEntityManager) => {
          let entity = await transactionalEntityManager.findOne(
            AssemblyLineConfig,
            {
              where: { plant, resourceId, shiftCode },
            },
          );
          if (entity) {
            Object.assign(entity, data);
            this.customLogger.debug(
              `AssemblyLineConfig with Plant ${plant}, Resource ${resourceId}, Shift ${shiftCode} is found`,
              context,
            );
