export type FailureClass =
  | 'NON_RETRYABLE' // Case 1: invalid/corrupted data
  | 'RETRYABLE' // Case 2: retryable SQL/server error
  | 'CONNECTION'; // Case 3: connectivity/timeout

/**
 * SQL Server error classification
 *
 * NON_RETRYABLE ERRORS (permanent data issues)
 * These errors indicate corrupted, invalid, or schema‑violating data.
 * Retrying the same batch will ALWAYS fail. → Switch to per‑event processing.
 *
 * 2627 - Violation of PRIMARY KEY or UNIQUE constraint
 *        Duplicate key/duplicate business identifier. Not retryable.
 *
 * 2601 - Duplicate key row in a unique index
 *        Same as 2627 but triggered by unique index instead of PK.
 *
 * 547  - FOREIGN KEY violation
 *        Child record references a non‑existent parent. Data issue.
 *
 * 245  - Conversion failed (e.g., string → int, invalid datetime)
 *        Means malformed/corrupted input data.
 *
 * 8152 - String or binary data would be truncated
 *        Value too long for the column; invalid input.
 *
 * 515  - Cannot insert NULL into a NOT NULL column
 *        Missing required fields in the payload.
 *
 * 8672 - The MERGE statement attempted to UPDATE or INSERT the same row more than once
 *        Source rowset contains duplicate rows matching the same target row.
 *        Retrying the same batch will ALWAYS fail. Refine the ON clause or deduplicate the source.
 *
 *
 * RETRYABLE ERRORS (transient SQL issues)
 * These are temporary problems; retrying usually succeeds. → Apply retry with backoff.
 *
 * 1205 - Deadlock victim
 *        SQL Server killed the transaction to resolve a deadlock.
 *
 * 40501 - Azure SQL throttling
 *         Server is busy/throttling requests. Retry after delay.
 *
 * 40197 - SQL Server service-level transient error
 *         Temporary platform internal issue.
 *
 * 40613 - Database temporarily unavailable
 *         Happens during failover or maintenance.
 *
 * 10928 - Resource limit reached (worker threads)
 *         SQL under heavy load; retry later.
 *
 * 10929 - Resource limit reached (CPU/memory throttling)
 *         SQL enforcing resource caps; retry later.
 * @param error - The error object thrown during SQL operations
 * @param error.message - The error message string for pattern matching
 * @param error.driverError - The original driver error object (if available) containing the SQL error number
 * @param error.driverError.number  - The SQL Server error number for classification
 * @param error.number  - Alternative location for SQL error number (some libraries put it here)
 * @returns Failure classification to determine retry strategy
 */
export function classifySqlFailure(error: {
  message?: string;
  driverError?: { number?: number };
  number?: number;
}): FailureClass {
  const message = (
    error?.message ||
    (error instanceof Error ? error.message : '') ||
    ''
  ).toLowerCase();
  const errorNumber = error?.driverError?.number ?? error?.number;

  // ---- Case Connectivity / timeouts ----
  if (
    message.includes('failed to connect') ||
    message.includes('connect timeout') ||
    message.includes('connection lost') ||
    message.includes('socket hang up') ||
    message.includes('econnreset') ||
    message.includes('etimedout') ||
    message.includes('host is unreachable') ||
    message.includes('enetwork') ||
    message.includes('could not connect')
  ) {
    return 'CONNECTION';
  }

  // By SQL Server error number (if available)
  const nonRetryableNums = new Set([2627, 2601, 547, 245, 8152, 515, 8672]);
  if (nonRetryableNums.has(Number(errorNumber))) return 'NON_RETRYABLE';

  const retryableNums = new Set([1205, 40_501, 40_197, 40_613, 10_928, 10_929]);
  if (retryableNums.has(Number(errorNumber))) return 'RETRYABLE';

  // By message patterns (non-retryable)
  if (
    message.includes('violation of unique') ||
    message.includes('duplicate key') ||
    message.includes('foreign key constraint') ||
    message.includes('cannot insert the value null') ||
    message.includes('conversion failed') ||
    message.includes('string or binary data would be truncated') ||
    message.includes('check constraint') ||
    message.includes('merge statement attempted to update or') // Covers "UPDATE or INSERT" and "UPDATE or DELETE" variants
  ) {
    return 'NON_RETRYABLE';
  }

  // By message patterns (retryable)
  if (
    message.includes('deadlock') ||
    message.includes('throttl') || // Throttled/throttling
    message.includes('resource limit') ||
    message.includes('is busy') ||
    message.includes('transient')
  ) {
    return 'RETRYABLE';
  }

  // Used as default for any error
  return 'RETRYABLE';
}

