import { Injectable, Logger } from '@nestjs/common';
import axios from 'axios';
import { Response } from 'express';
import { ProbesConfigService } from '@/config/probes/probes.service';

@Injectable()
export class ProbesService {
  private readonly healthMessage = 'mesx/resource-di [OK]';

  public constructor(
    private readonly probesConfigService: ProbesConfigService,
  ) {}

  public getHello(): string {
    return this.healthMessage;
  }

  /**
   * Performs a health check by calling the DAPR health endpoint
   * @param resp Express response object to send the result
   * @returns Promise resolving to void
   */
  public async checkHealth(resp: Response): Promise<void> {
    try {
      // Simulate an error for testing purposes

      const response = await axios.get(this.probesConfigService.daprCheckUrl, {
        timeout: this.probesConfigService.checkTimeoutMs,
      });

      const statusCode = response.status;
      resp.status(200).json(`Status Code: ${statusCode}`);
    } catch (error) {
      const statusCode = error.response?.status ?? 'Unknown';

      if (statusCode === 'Unknown') {
        resp.status(500).json({});
        Logger.error(
          `Health check failed with error: ${error.message}`,
          error.stack,
        );
      } else {
        const responseBody = error.response?.data ?? 'No response body';
        const statusText = error.response?.statusText ?? 'No status Text';
        resp.status(500).json({ statusCode, responseBody });
        Logger.error(
          `Health check failed with status code: ${statusCode},status text ${statusText}, response body: ${responseBody}`,
        );
      }
    }
  }
}

