import {
  JobsLogContext,
  telemetryMetrics,
  PROCESSING_STATUS,
} from '@mesx/common-lib';
import { Injectable } from '@nestjs/common';
import { OnEvent } from '@nestjs/event-emitter';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { RoutingPrt } from './routing-prt.entity';
import { AppLogger } from '@/common/logger/app-logger';

@Injectable()
export class RoutingPrtService {
  private static createLogContext(
    method: string,
    plant?: number,
    object?: string,
  ): JobsLogContext {
    return {
      method,
      object,
      plant,
      service: RoutingPrtService.name,
    };
  }

  public constructor(
    @InjectRepository(RoutingPrt)
    private readonly repo: Repository<RoutingPrt>,
    private readonly customLogger: AppLogger,
  ) {}

  @OnEvent('routingPrt.c')
  private async create(payload: RoutingPrt): Promise<void> {
    await this.upsert(payload, 'create');
  }

  @OnEvent('routingPrt.u')
  private async update(payload: RoutingPrt): Promise<void> {
    await this.upsert(payload, 'update');
  }

  @OnEvent('routingPrt.r')
  private async readSnapshot(payload: RoutingPrt): Promise<void> {
    await this.upsert(payload, 'readSnapshot');
  }

  private async upsert(payload: RoutingPrt, method: string): Promise<void> {
    const context = RoutingPrtService.createLogContext(
      method,
      payload?.plant,
      payload?.toolId,
    );

    if (!payload) {
      this.customLogger.error(`Payload is empty or undefined`, context);
      return;
    }

    try {
      const { localTool, plant, toolId } = payload;
      const sqlStartTime = Date.now();
      await this.repo.upsert(
        {
          localTool,
          plant,
          toolId,
          updatedAt: () => 'SYSUTCDATETIME()',
        },
        ['plant', 'toolId'],
      );
      const sqlDuration = Date.now() - sqlStartTime;
      telemetryMetrics.trackEventProcessingDuration(
        sqlDuration,
        PROCESSING_STATUS.SQL,
        String(plant),
        'routing-prt',
      );
      telemetryMetrics.trackEventProcessed(
        PROCESSING_STATUS.SQL,
        String(plant),
        'routing-prt',
      );
      this.customLogger.debug(
        `Successfully upserted RoutingPrt with Plant ${plant}, Tool ${toolId}`,
        context,
      );
    } catch (error) {
      this.customLogger.error(
        `Error upserting (insert or update) RoutingPrt in database: ${error.message}`,
        context,
      );
    }
  }
}

