@Injectable()
export class ShiftTrackingDtlService implements BeforeApplicationShutdown {
  private readonly shiftTrackingDtlBufferByPlant: Map<
    number,
    EntityBuffer<ShiftTrackingDtl>
  >;

  private lastFlushTime: number;

  private readonly bufferConfig: FlushConfig;

  private totalBufferedEvents: number;

  private circuitBreakerOpen = false;

  private connectivityCheckTimer: ReturnType<typeof setTimeout>;

  public constructor(
    @InjectRepository(ShiftTrackingDtl)
    private readonly shiftTrackingDtlRepository: Repository<ShiftTrackingDtl>,
    private readonly customLogger: AppLogger,
    private readonly telemetryConfigService: TelemetryConfigService,
    private readonly storedLogger: StoredLoggerService,
    private readonly configService: EventhubSdkConfigService,
    private readonly eventHubProducerService: EventHubProducerService,
  ) {
    this.shiftTrackingDtlBufferByPlant = new Map<
      number,
      EntityBuffer<ShiftTrackingDtl>
    >();
    this.lastFlushTime = Date.now();
    this.totalBufferedEvents = 0;
    this.bufferConfig = {
      maxBatchSize: this.configService.commonMaxBatchSize,
      maxFlushIntervalMs: this.configService.commonUpsertInterval,
    };
  }

  public async beforeApplicationShutdown(): Promise<void> {
    // Flush everything remaining to sql db
    await this.flushBufferToDB();
  }

  @OnEvent('shiftTrackingDtl.c')
  private async create(payload: ShiftTrackingDtl): Promise<void> {
    const context: JobsLogContext = {
      method: 'create',
      service: 'ShiftTrackingDtlService',
    };
    if (!payload)
      return this.customLogger.verbose(`payload is empty${payload}`, context);
    try {
      await this.upsertByComposite(payload, context);
    } catch (error) {
      this.customLogger.error(
        `Error in upsert(create) for shift tracking dtl: ${error.message}`,
        context,
        error.stack,
      );
    }
    return undefined;
  }

  @OnEvent('shiftTrackingDtl.u')
  private async update(payload: ShiftTrackingDtl): Promise<void> {
    const context: JobsLogContext = {
      method: 'update',
      service: 'ShiftTrackingDtlService',
    };
    if (!payload)
      return this.customLogger.verbose(`payload is empty${payload}`, context);
    try {
      await this.upsertByComposite(payload, context);
    } catch (error) {
      this.customLogger.error(
        `Error updating shift tracking dtl record: ${error.message}`,
        context,
        error.stack,
      );
    }
    return undefined;
  }

  @OnEvent('shiftTrackingDtl.r')
  private async snapshot(payload: ShiftTrackingDtl): Promise<void> {
    const context: JobsLogContext = {
      method: 'snapshot',
      service: 'ShiftTrackingDtlService',
    };
    if (!payload) {
      return this.customLogger.verbose(`payload is empty${payload}`, context);
    }
    try {
      await this.upsertByComposite(payload, context);
      this.customLogger.debug(`ShiftTrackingDtl snapshot upserted`, context);
    } catch (error) {
      this.customLogger.error(
        `Error upserting shift tracking dtl snapshot record: ${error.message}`,
        context,
        error.stack,
      );
    }
    return undefined;
  }

  /**
   * Upsert a ShiftTrackingDtl row using composite natural key (plant, resourceId, dateHourFrom, materialId and toolId).
   * @param payload Incoming shift tracking dtl payload
   * @param context Logging context
   */
  private async upsertByComposite(
    payload: ShiftTrackingDtl,
    context: JobsLogContext,
  ): Promise<void> {
    const { plant, resourceId, dateHourFrom } = payload;
    try {
      const eventPrimaryKey = `${plant}|${resourceId}|${dateHourFrom}|${payload.materialId}|${payload.toolId}`;
      await this.addEventToBuffer(payload, eventPrimaryKey);

      this.customLogger.debug(
        `Upserted ShiftTrackingDtl composite (${plant}-${resourceId}-${dateHourFrom.toISOString()}-${payload.materialId}-${payload.toolId})`,
        context,
      );
    } catch (error) {
      this.customLogger.debug(
        `Error upserting ShiftTrackingDtl composite (${plant}-${resourceId}-${dateHourFrom.toISOString()}-${payload.materialId}-${payload.toolId})`,
        context,
      );
      // Unrelated error → rethrow
      throw error;
    }
  }

  private async addEventToBuffer(
    payload: ShiftTrackingDtl,
    eventPrimaryKey: string,
  ): Promise<void> {
    const { plant } = payload;
    const plantBuffer = this.getOrCreateBuffer(plant);
    const existing = plantBuffer.activeList.get(eventPrimaryKey) || {};
    plantBuffer.activeList.set(eventPrimaryKey, {
      ...existing,
      ...payload,
      updatedAt: () => 'SYSUTCDATETIME()',
    });
    this.totalBufferedEvents += 1;
    if (
      this.totalBufferedEvents > this.bufferConfig.maxBatchSize ||
      (Date.now() - this.lastFlushTime >=
        this.bufferConfig.maxFlushIntervalMs &&
        this.totalBufferedEvents > 0)
    ) {
      await this.flushBufferToDB();
    }
  }

  private getOrCreateBuffer(plant: number): EntityBuffer<ShiftTrackingDtl> {
    let buffer = this.shiftTrackingDtlBufferByPlant.get(plant);
    if (!buffer) {
      buffer = {
        activeList: new Map(),
      };
      this.shiftTrackingDtlBufferByPlant.set(plant, buffer);
    }
    return buffer;
  }

  // ---------------- FLUSH LOGIC ----------------

  public async flushBufferToDB(): Promise<void> {
    const totalEventsProcessedInBulk = this.totalBufferedEvents;
    const totalRecords: Array<QueryDeepPartialEntity<ShiftTrackingDtl>> = [];
    const listofBufferedPlants: Array<number> = [
      ...this.shiftTrackingDtlBufferByPlant.keys(),
    ];
    for (const plant of listofBufferedPlants) {
      const plantBuffer = this.shiftTrackingDtlBufferByPlant.get(plant);
      if (plantBuffer && plantBuffer.activeList.size > 0) {
        // 🔥 SAFE SWAP
        const records: Array<QueryDeepPartialEntity<ShiftTrackingDtl>> = [
          ...plantBuffer.activeList.values(),
        ];
        plantBuffer.activeList = new Map();

        totalRecords.push(...records);
      }
    }
    this.lastFlushTime = Date.now();
    this.totalBufferedEvents = 0;

    try {
      const sqlStartTime = Date.now();

      await (this.circuitBreakerOpen
        ? this.publishToDLQ(totalRecords)
        : this.shiftTrackingDtlRepository.upsert(totalRecords, {
            conflictPaths: [
              'plant',
              'resourceId',
              'dateHourFrom',
              'materialId',
              'toolId',
            ],
          }));

      const sqlDuration = Date.now() - sqlStartTime;

      const { enableTelemetry } = this.telemetryConfigService;
      // Track SQL operation metric using the singleton
      if (enableTelemetry) {
        telemetryMetrics.trackEventProcessingDuration(
          sqlDuration,
          PROCESSING_STATUS.SQL,
          '*', // All plants
          'shift-tracking-dtl',
        );
        telemetryMetrics.trackCounter(
          'event_processed_count',
          totalEventsProcessedInBulk,
          {
            plantCode: '*', // All plants
            status: PROCESSING_STATUS.SQL,
            topic: 'shift-tracking-dtl',
          },
        );
      }
    } catch (error) {
      const failureClass = classifySqlFailure(error);

      switch (failureClass) {
        case 'NON_RETRYABLE': {
          // Case 1 → per-event sequential, bad → Cosmos, good → SQL
          await this.processRecordsSequentially(totalRecords);
          break;
        }

        case 'RETRYABLE': {
          // Case 2 → retry with backoff; on exhaustion:
          // - send batch to DLQ
          // - if failures dominated by connection/timeout → open circuit
          await this.retryFailedUpsertWithBackoff(totalRecords);
          break;
        }

        case 'CONNECTION': {
          // Case 3 → open circuit immediately, send batch to DLQ
          await this.startSqlConnectivityCheck();
          await this.publishToDLQ(totalRecords);
          break;
        }
        default: {
          break;
        }
      }
    }
  }

  private async startSqlConnectivityCheck(): Promise<void> {
    const context: JobsLogContext = {
      method: 'startSqlConnectivityCheck',
      service: 'ShiftTrackingDtlService',
    };

    this.circuitBreakerOpen = true;

    if (this.connectivityCheckTimer) return; // Already running

    const probe = async (): Promise<void> => {
      try {
        await this.shiftTrackingDtlRepository.query('SELECT 1');
        this.customLogger.log('SQL connectivity restored', context);
        this.stopSqlConnectivityCheck();
        // Important: stop scheduling new timeouts
      } catch {
        // SQL still down, schedule next probe
        this.connectivityCheckTimer = setTimeout(probe, 10_000);
      }
    };

    this.connectivityCheckTimer = setTimeout(probe, 10_000);
  }

  private stopSqlConnectivityCheck(): void {
    if (this.connectivityCheckTimer) {
      clearTimeout(this.connectivityCheckTimer);
    }
    this.circuitBreakerOpen = false;
  }

  private async publishToDLQ(
    records: Array<QueryDeepPartialEntity<ShiftTrackingDtl>>,
  ): Promise<void> {
    const context: JobsLogContext = {
      method: 'publishToDLQ',
      service: 'ShiftTrackingDtlService',
    };

    try {
      const failureTimestamp = new Date().toISOString();
      const messages = records.map((record) => ({
        plant: Number(record.plant),
        payload: { ...record, updatedAt: failureTimestamp },
        destinationTable: 'shift_tracking_dtl' as const,
      }));

      await this.eventHubProducerService.sendMessages(
        messages,
        failureTimestamp,
      );
      this.customLogger.debug(
        `Successfully published ${messages.length} records to DLQ`,
        context,
      );
    } catch (error) {
      this.customLogger.error(
        `Failed to publish batch to DLQ: ${error instanceof Error ? error.message : String(error)}`,
        context,
        error instanceof Error ? error : new Error(String(error)),
      );
    }
  }

  private async processRecordsSequentially(
    records: Array<QueryDeepPartialEntity<ShiftTrackingDtl>>,
  ): Promise<void> {
    const context: JobsLogContext = {
      method: 'processRecordsSequentially',
      service: 'ShiftTrackingDtlService',
    };
    for (const record of records) {
      try {
        await this.shiftTrackingDtlRepository.upsert(record, {
          conflictPaths: [
            'plant',
            'resourceId',
            'dateHourFrom',
            'materialId',
            'toolId',
          ],
        });
      } catch (error) {
        this.customLogger.error(
          `Error processing shift tracking DTL record sequentially for plant ${record.plant}: ${error}`,
          context,
        );
        // Flush to Cosmos failed record for later analysis
        await this.flushRecordsToCosmos([record], `Upsert error ${error}`);
      }
    }
  }

  private async retryFailedUpsertWithBackoff(
    records: Array<QueryDeepPartialEntity<ShiftTrackingDtl>>,
    attempt = 1,
  ): Promise<void> {
    const context: JobsLogContext = {
      method: 'retryFailedUpsertWithBackoff',
      service: 'ShiftTrackingDtlService',
    };

    const options = {
      retries: 3,
      initialDelayMs: 100,
    };
    const delay = options.initialDelayMs * 3 ** (attempt - 1);

    try {
      await this.shiftTrackingDtlRepository.upsert(records, {
        conflictPaths: [
          'plant',
          'resourceId',
          'dateHourFrom',
          'materialId',
          'toolId',
        ],
      });
      return undefined; // Success
    } catch (error) {
      if (attempt >= options.retries) {
        this.customLogger.error(
          `Retry attempts exhausted for batch upsert. Error: ${error}`,
          context,
        );
        // Send batch to DLQ
        await this.publishToDLQ(records);
        return undefined;
      }

      await new Promise((resolve) => {
        setTimeout(resolve, delay);
      });
      return this.retryFailedUpsertWithBackoff(records, attempt + 1);
    }
  }

  private async flushRecordsToCosmos(
    records: Array<QueryDeepPartialEntity<ShiftTrackingDtl>>,
    reason?: string,
  ): Promise<void> {
    // Split the records by plant to benefit from Cosmos partition and make it easier to reprocess per plant
    const recordsByPlant = new Map<
      number,
      Array<QueryDeepPartialEntity<ShiftTrackingDtl>>
    >();

    for (const record of records) {
      const plant = Number(record.plant);

      if (!recordsByPlant.has(plant)) {
        recordsByPlant.set(plant, []);
      }

      recordsByPlant.get(plant)?.push(record);
    }
    await Promise.allSettled(
      [...recordsByPlant.entries()].map(([plant, plantRecords]) =>
        this.storedLogger.functionalLog(
          {
            applicationName: 'rsrce-di',
            context: {
              destinationTable: 'shift_tracking_dtl',
              reason,
              records: plantRecords,
            },
            errorCode: ERROR_CODES.failedShiftTrackingDtlEvents.code, // Error code dedicated for shift-tracking-dtl events
            objectId: `EventHub`,
            plant: Number(plant),
            user: '',
          },
          {
            aggregateErrorsByDay: false,
            usefireAndForget: false,
          },
        ),
      ),
    );
  }
}

